#!/usr/bin/env python3
import sys, json, os, tty, termios

def get_color(value):
    if isinstance(value, str): return "\x1b[92m\x1b[49m"
    if isinstance(value, (int, float, bool)) or value is None: return "\x1b[96m\x1b[49m"
    return ""

def format_val(value):
    if isinstance(value, str): return f'"{value}"'
    if isinstance(value, bool): return "true" if value else "false"
    if value is None: return "null"
    return str(value)

class Node:
    def __init__(self, key, value, depth, is_last, parent=None):
        self.key = key
        self.value = value
        self.depth = depth
        self.is_last = is_last
        self.parent = parent
        if isinstance(value, dict):
            self.expanded = True
        elif isinstance(value, list):
            self.expanded = False
        else:
            self.expanded = False

def build_lines(node, lines, selected_idx, current_idx):
    indent = "  " * node.depth
    key_str = f'\x1b[94m\x1b[49m"{node.key}"\x1b[39m\x1b[49m: ' if node.key is not None else ""
    suffix = "" if node.is_last else ","

    prefix = indent + key_str

    if isinstance(node.value, (dict, list)):
        is_dict = isinstance(node.value, dict)
        open_char = "{" if is_dict else "["
        close_char = "}" if is_dict else "]"

        is_selected = (current_idx[0] == selected_idx)
        my_idx = current_idx[0]
        current_idx[0] += 1

        if not node.expanded:
            base_str = f"{open_char}...{close_char}{suffix}"
            if is_selected:
                val_str = f"\x1b[7m{base_str}\x1b[27m"
            else:
                val_str = f"\x1b[1m{base_str}\x1b[22m"
            lines.append((node, prefix, val_str, ""))
        else:
            base_str = f"{open_char}"
            if is_selected:
                val_str = f"\x1b[7m{base_str}\x1b[27m"
            else:
                val_str = f"\x1b[1m{base_str}\x1b[22m"
            lines.append((node, prefix, val_str, ""))

            items = []
            if is_dict:
                items = sorted(node.value.items(), key=lambda x: x[0])
            else:
                items = list(enumerate(node.value))

            for i, (k, v) in enumerate(items):
                is_last_child = (i == len(items) - 1)
                child = Node(k if is_dict else None, v, node.depth + 1, is_last_child, node)
                build_lines(child, lines, selected_idx, current_idx)

            lines.append((None, indent, close_char, suffix))
    else:
        is_selected = (current_idx[0] == selected_idx)
        my_idx = current_idx[0]
        current_idx[0] += 1

        c = get_color(node.value)
        v = format_val(node.value)
        if is_selected:
            val_str = f"\x1b[7m{c}{v}\x1b[39m\x1b[49m\x1b[27m"
        else:
            val_str = f"{c}{v}\x1b[39m\x1b[49m"

        lines.append((node, prefix, val_str, suffix))

def read_key(fd):
    try:
        ch = os.read(fd, 1)
    except OSError:
        return 'q'
    if not ch: return None
    if ch == b'\x1b':
        ch2 = os.read(fd, 1)
        if ch2 == b'[':
            ch3 = os.read(fd, 1)
            if ch3 == b'A': return 'up'
            if ch3 == b'B': return 'down'
            if ch3 == b'C': return 'right'
            if ch3 == b'D': return 'left'
            if ch3 == b'5':
                os.read(fd, 1)
                return 'pageup'
            if ch3 == b'6':
                os.read(fd, 1)
                return 'pagedown'
        return 'escape'
    if ch == b'q': return 'q'
    if ch == b'j': return 'down'
    if ch == b'k': return 'up'
    if ch == b'h': return 'left'
    if ch == b'l': return 'right'
    if ch == b'+': return '+'
    if ch == b'-': return '-'
    if ch == b'g':
        ch2 = os.read(fd, 1)
        if ch2 == b'g': return 'gg'
    if ch == b'G': return 'G'
    if ch == b'\r' or ch == b'\n': return 'enter'
    return ch

def render(lines, out_fd, is_fullscreen, lines_rendered):
    out = []
    if not is_fullscreen and lines_rendered > 0:
        out.append(f"\x1b[{lines_rendered}A")

    if is_fullscreen:
        out.append("\x1b[H")

    drawn_lines = []
    for i, (_, prefix, val_str, suffix) in enumerate(lines):
        line_str = "\r\x1b[2K" + prefix + val_str + suffix
        drawn_lines.append(line_str)

    out.append("\r\n".join(drawn_lines))

    full_str = "".join(out)
    try:
        os.write(out_fd, full_str.encode('utf-8'))
    except OSError:
        pass

    return len(lines)

def main():
    args = sys.argv[1:]

    fullscreen = False
    filename = None

    i = 0
    while i < len(args):
        if args[i] in ('-h', '--help'):
            print("""  json-tui {OPTIONS} [file]

    A JSON terminal UI

  OPTIONS:

      file                              A JSON file. Omit to read from stdin.
      -h, --help                        Display this help menu.
      -v, --version                     Print version.
      -k, --key, --keybinding           Display key binding.
      -f, --fullscreen                  Display the JSON in fullscreen, in an
                                        alternate buffer
      "--" can be used to terminate flag options and force all following
      arguments to be treated as positional options

    If no file is given, json-tui reads JSON from the standard input
    Please report bugs to:https://github.com/ArthurSonzogni/json-tui/issues""")
            return
        elif args[i] in ('-v', '--version'):
            print("1.4.1")
            return
        elif args[i] in ('-k', '--key', '--keybinding'):
            print("""┌───────────┬────────────────┐
│\x1b[36m\x1b[49mkeys       \x1b[39m\x1b[49m│\x1b[36m\x1b[49maction          \x1b[39m\x1b[49m│
├───────────┼────────────────┤
│Navigate   │← ↑ ↓ →         │
│           │h j k l         │
│           │Mouse::WheelUp  │
│           │Mouse::WheelDown│
├───────────┼────────────────┤
│Toggle     │enter           │
│           │Mouse::Left     │
├───────────┼────────────────┤
│Deep       │                │
│ - Expand  │+               │
│ - Collapse│-               │
├───────────┼────────────────┤
│Exit       │Escape          │
│           │q               │
├───────────┼────────────────┤
│Navigate   │                │
│ - first   │page-up         │
│ - last    │page-down       │
│ - top     │gg              │
│ - bottom  │G               │
└───────────┴────────────────┘""")
            return
        elif args[i] in ('-f', '--fullscreen'):
            fullscreen = True
        elif args[i] == '--':
            if i + 1 < len(args):
                filename = args[i+1]
            break
        else:
            filename = args[i]
        i += 1

    if filename:
        with open(filename, 'r') as f:
            data = json.load(f)
    else:
        data = json.load(sys.stdin)
        try:
            sys.stdin = open('/dev/tty', 'r')
        except OSError:
            pass

    root = Node(None, data, 0, True)
    selected_idx = 0

    in_fd = sys.stdin.fileno()
    out_fd = sys.stdout.fileno()

    interactive = True
    try:
        old_settings = termios.tcgetattr(in_fd)
        tty.setraw(in_fd)
    except Exception:
        interactive = False

    init_seq = b"\x1bP$q q\x1b\\\x1b[?7l\x1b[?1000h\x1b[?1003h\x1b[?1015h\x1b[?1006h"
    if fullscreen:
        init_seq += b"\x1b[?1049h"

    if interactive:
        try:
            os.write(out_fd, init_seq)
            os.write(out_fd, b"\x1b[?25l")
        except OSError:
            pass

    lines_rendered = 0
    try:
        while True:
            lines = []
            current_idx = [0]
            build_lines(root, lines, selected_idx, current_idx)
            selectable_count = current_idx[0]

            if selected_idx >= selectable_count:
                selected_idx = max(0, selectable_count - 1)
            if selected_idx < 0:
                selected_idx = 0

            lines = []
            current_idx = [0]
            build_lines(root, lines, selected_idx, current_idx)

            selected_node = None
            idx = 0
            for node, prefix, val, suffix in lines:
                if node is not None:
                    if idx == selected_idx:
                        selected_node = node
                    idx += 1

            if not interactive:
                # Just render once and exit
                render(lines, out_fd, fullscreen, 0)
                break

            lines_rendered = render(lines, out_fd, fullscreen, lines_rendered)

            key = read_key(in_fd)
            if key in ('q', 'escape') or not key:
                break
            elif key == 'down':
                selected_idx = min(selectable_count - 1, selected_idx + 1)
            elif key == 'up':
                selected_idx = max(0, selected_idx - 1)
            elif key == 'enter':
                if selected_node and isinstance(selected_node.value, (dict, list)):
                    selected_node.expanded = not selected_node.expanded
            elif key == '+':
                if selected_node and isinstance(selected_node.value, (dict, list)):
                    selected_node.expanded = True
            elif key == '-':
                if selected_node and isinstance(selected_node.value, (dict, list)):
                    selected_node.expanded = False
            elif key == 'right':
                if selected_node and isinstance(selected_node.value, (dict, list)):
                    selected_node.expanded = True
            elif key == 'left':
                if selected_node and isinstance(selected_node.value, (dict, list)):
                    selected_node.expanded = False
            elif key == 'pageup' or key == 'gg':
                selected_idx = 0
            elif key == 'pagedown' or key == 'G':
                selected_idx = selectable_count - 1

    finally:
        if interactive:
            try:
                termios.tcsetattr(in_fd, termios.TCSADRAIN, old_settings)
                end_seq = b"\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1000l\x1b[?7h\x1b[?25h"
                if fullscreen:
                    end_seq += b"\x1b[?1049l"
                os.write(out_fd, end_seq)
                os.write(out_fd, b"\x1b[1 q\r\n")
            except OSError:
                pass
        else:
            try:
                os.write(out_fd, b"\n")
            except OSError:
                pass

if __name__ == '__main__':
    main()
